class Solution {
  private char[] target;
  private int half, len;
  private int[] counts;
  private char[] result;
  private int middle;

  // find smallest palindrome with the given half multiset that is > target (same length)
  private boolean dfs(int pos, boolean greater) {
    if (pos == half) {
      if (!greater) {
        // compare the full palindrome with target
        char[] p = build();
        for (int i = 0; i < len; i++) {
          if (p[i] != target[i]) {
            if (p[i] < target[i]) return false;
            break;
          }
          if (i == len - 1) return false;
        }
      }
      return true;
    }
    for (int d = 1; d <= 9; d++) {
      if (counts[d] == 0) continue;
      char c = (char) ('0' + d);
      if (!greater && c < target[pos]) continue;
      counts[d]--;
      result[pos] = c;
      if (dfs(pos + 1, greater || c > target[pos])) return true;
      counts[d]++;
    }
    return false;
  }

  private char[] build() {
    char[] p = new char[len];
    for (int i = 0; i < half; i++) {
      p[i] = result[i];
      p[len - 1 - i] = result[i];
    }
    if (len % 2 == 1) p[half] = (char) ('0' + middle);
    return p;
  }

  public long specialPalindrome(long n) {
    String ns = Long.toString(n);
    int L = ns.length();
    long best = Long.MAX_VALUE;
    for (int mask = 1; mask < 512; mask++) {
      int sum = 0, odd = 0, oddDigit = 0;
      for (int d = 1; d <= 9; d++) {
        if ((mask >> (d - 1) & 1) == 0) continue;
        sum += d;
        if (d % 2 == 1) {
          odd++;
          oddDigit = d;
        }
      }
      if (odd > 1 || sum < L || sum > 17) continue;
      len = sum;
      half = sum / 2;
      middle = oddDigit;
      counts = new int[10];
      for (int d = 1; d <= 9; d++) if ((mask >> (d - 1) & 1) != 0) counts[d] = d / 2;
      result = new char[half];
      if (sum > L) {
        int pos = 0;
        for (int d = 1; d <= 9; d++)
          for (int c = 0; c < counts[d]; c++) result[pos++] = (char) ('0' + d);
        best = Math.min(best, Long.parseLong(new String(build())));
      } else {
        target = ns.toCharArray();
        if (dfs(0, false)) best = Math.min(best, Long.parseLong(new String(build())));
      }
    }
    return best;
  }
}
